    "Discord is known to punish users of scripts or plugins that modify the completion of Quests. Modifying the completion of Quests is against Discord's": "Discord est connu pour sanctionner les utilisateurs de scripts ou plugins qui modifient l'accomplissement des quêtes. C'est contraire aux",
    "Terms of Service": "Conditions d'utilisation",
    "The punishment consists of a temporary or permanent loss of access to Quests and their rewards.": "La sanction est une perte temporaire ou définitive de l'accès aux quêtes et à leurs récompenses.",
    "The punishment also consists of an account standing violation which lasts 2 years per violation.": "La sanction inclut aussi une infraction au statut du compte qui dure 2 ans par infraction.",
    "Due to the various methods Discord uses to track users, there's no way to realistically evade detection. If you proceed, understand that Discord likely will detect your use at some point.": "Vu les nombreuses méthodes de suivi de Discord, il n'existe aucun moyen réaliste d'éviter la détection. Si vous continuez, sachez que Discord le détectera probablement un jour.",
