    "This fix isn't perfect, so you may have to reload the search bar to fix issues.": "Ce correctif n'est pas parfait : en cas de souci, rechargez la barre de recherche.",
    "Discord only allows a max offset of 5000 (this is what causes the magnifying glass error). This means that you can only see precisely 5000 messages into the past, and 5000 messages into the future (when sorting by old). This plugin just jumps to the opposite sorting method to try get around Discord's restriction, but if there is a large search result, and you try to view a message that is unobtainable with both methods of sorting, the plugin will simply show offset 0 (either newest or oldest message depending on the sorting method).": "Discord n'autorise qu'un décalage maximal de 5000 (d'où l'erreur de la loupe). Vous ne voyez donc que 5000 messages dans le passé, et 5000 dans le futur (tri par ancienneté). Ce plugin passe au tri inverse pour contourner la limite, mais si le résultat est très grand et qu'un message est inaccessible dans les deux sens, il affichera le décalage 0 (message le plus récent ou le plus ancien selon le tri).",
